function validate([k, prices]) {
  if (!Number.isInteger(k) || k < 1 || k > 100) return 'k is a whole number from 1 to 100.';
  if (prices.length < 1 || prices.length > 1000) return 'prices needs 1 to 1000 values.';
  if (prices.some(p => !Number.isInteger(p) || p < 0 || p > 1000)) return 'Each price is a whole number from 0 to 1000.';
  return null;
}

