function maxProfit(k, prices) {
  // Try every choice on every day: wait, buy (if allowed) or sell (if holding).
  function best(day, left, boughtAt) {
    if (day === prices.length) return 0;
    let result = best(day + 1, left, boughtAt);
    if (boughtAt === null && left > 0) result = Math.max(result, best(day + 1, left, prices[day]));
    if (boughtAt !== null) result = Math.max(result, prices[day] - boughtAt + best(day + 1, left - 1, null));
    return result;
  }
  return best(0, k, null);
}

