function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const k = 1 + pick(100);
    const prices = Array.from({ length: 1000 }, () => pick(1001));
    return [k, prices];
  }
  const n = 1 + pick(10);
  const top = rand() < 0.6 ? 10 : 1000;
  const prices = [];
  for (let i = 0; i < n; i++) {
    const roll = rand();
    if (i > 0 && roll < 0.15) prices.push(prices[i - 1]);
    else if (i > 0 && roll < 0.3) prices.push(Math.max(0, Math.min(top, prices[i - 1] + pick(5) - 2)));
    else prices.push(pick(top + 1));
  }
  const k = rand() < 0.15 ? 1 + pick(100) : 1 + pick(4);
  return [k, prices];
}
